//! File-type icons (Material Icon Theme SVGs, bundled as Qt resources).
//! `url_for` picks the icon for a file name.

// `ICONS`: the bundled icon ids, sorted (generated by build.rs).
include!(concat!(env!("OUT_DIR"), "/file_icons.rs"));

const PREFIX: &str = "qrc:/qt/qml/harlo/icons/file-types/";
const FALLBACK: &str = "document";

fn known(id: &str) -> bool {
    ICONS.binary_search(&id).is_ok()
}

/// Whole file names (lowercase) with an icon of their own.
fn by_file_name(name: &str) -> Option<&'static str> {
    Some(match name {
        "dockerfile" | "containerfile" | "docker-compose.yml" | "docker-compose.yaml" | "compose.yml" | "compose.yaml" | ".dockerignore" => "docker",
        "makefile" | "gnumakefile" => "makefile",
        "cmakelists.txt" => "cmake",
        "meson.build" => "meson",
        "justfile" | ".justfile" => "just",
        "package.json" | "package-lock.json" | ".npmrc" | ".npmignore" => "npm",
        "yarn.lock" | ".yarnrc" | ".yarnrc.yml" => "yarn",
        "pnpm-lock.yaml" | "pnpm-workspace.yaml" => "pnpm",
        "bun.lock" | "bun.lockb" | "bunfig.toml" => "bun",
        "cargo.toml" | "cargo.lock" => "rust",
        "go.mod" | "go.sum" | "go.work" => "go-mod",
        "gemfile" | "gemfile.lock" => "gemfile",
        "rakefile" | "podfile" | "vagrantfile" | "brewfile" => "ruby",
        "pyproject.toml" | "requirements.txt" | "setup.py" | "setup.cfg" | "pipfile" | "pipfile.lock" | ".python-version" => "python-misc",
        "poetry.lock" => "poetry",
        "uv.lock" => "uv",
        "tsconfig.json" => "tsconfig",
        "jsconfig.json" => "jsconfig",
        ".gitignore" | ".gitattributes" | ".gitmodules" | ".gitkeep" | ".git-blame-ignore-revs" | ".mailmap" => "git",
        ".editorconfig" => "editorconfig",
        ".prettierrc" | ".prettierignore" | "prettier.config.js" => "prettier",
        ".eslintrc" | ".eslintignore" | "eslint.config.js" | "eslint.config.mjs" => "eslint",
        ".babelrc" | "babel.config.js" => "babel",
        ".nvmrc" | ".node-version" => "nodejs",
        "license" | "license.md" | "license.txt" | "licence" | "copying" | "unlicense" => "certificate",
        "readme" | "readme.md" | "readme.txt" => "readme",
        "changelog" | "changelog.md" | "changes.md" | "history.md" => "changelog",
        "contributing.md" => "contributing",
        "code_of_conduct.md" => "conduct",
        "authors" | "authors.md" | "contributors" => "authors",
        "codeowners" => "codeowners",
        "security.md" => "verified",
        "todo" | "todo.md" => "todo",
        "claude.md" => "claude",
        "agents.md" => "markdown",
        "caddyfile" => "caddy",
        "procfile" => "heroku",
        "robots.txt" => "robots",
        "flake.nix" | "flake.lock" | "default.nix" | "shell.nix" => "nix",
        "vite.config.ts" | "vite.config.js" | "vite.config.mjs" => "vite",
        "vitest.config.ts" | "vitest.config.js" => "vitest",
        "tailwind.config.js" | "tailwind.config.ts" => "tailwindcss",
        "postcss.config.js" | "postcss.config.cjs" | "postcss.config.mjs" => "postcss",
        "renovate.json" => "renovate",
        "biome.json" | "biome.jsonc" => "biome",
        "turbo.json" => "turborepo",
        "vercel.json" => "vercel",
        "netlify.toml" => "netlify",
        "deno.json" | "deno.jsonc" => "deno",
        "knip.json" => "knip",
        ".env" => "tune",
        _ => return None,
    })
}

