/// The icon id for a file name or path.
pub fn icon_for(path: &str) -> &'static str {
    let name = path.rsplit(['/', '\\']).next().unwrap_or(path).to_lowercase();
    let pick = |id: &'static str| known(id).then_some(id);
    if let Some(id) = by_file_name(&name).and_then(pick) {
        return id;
    }
    if name.starts_with(".env") {
        return pick("tune").unwrap_or(FALLBACK);
    }
    // Compound suffixes: tests, type declarations.
    for (suffix, id) in [
        (".d.ts", "typescript-def"),
        (".test.ts", "test-ts"),
        (".spec.ts", "test-ts"),
        (".test.tsx", "test-jsx"),
        (".spec.tsx", "test-jsx"),
        (".test.js", "test-js"),
        (".spec.js", "test-js"),
        (".test.jsx", "test-jsx"),
        (".spec.jsx", "test-jsx"),
    ] {
        if name.ends_with(suffix)
            && let Some(id) = pick(id)
        {
            return id;
        }
    }
    let Some((_, ext)) = name.rsplit_once('.').filter(|(stem, _)| !stem.is_empty()) else {
        return FALLBACK;
    };
    if let Some(id) = by_extension(ext).and_then(pick) {
        return id;
    }
    // Many icons are named after their extension (go, lua, css, vue, zig…).
    ICONS.iter().copied().find(|id| *id == ext).unwrap_or(FALLBACK)
}

/// A `qrc:` URL for the file's icon, usable as an Image source.
pub fn url_for(path: &str) -> String {
    format!("{PREFIX}{}.svg", icon_for(path))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn picks_icons() {
        assert!(ICONS.windows(2).all(|w| w[0] < w[1]), "ICONS must be sorted");
        assert_eq!(icon_for("src/main.rs"), "rust");
        assert_eq!(icon_for("Cargo.toml"), "rust");
        assert_eq!(icon_for("/a/b/README.md"), "readme");
        assert_eq!(icon_for("notes.md"), "markdown");
        assert_eq!(icon_for("Dockerfile"), "docker");
        assert_eq!(icon_for(".env.local"), "tune");
        assert_eq!(icon_for(".gitignore"), "git");
        assert_eq!(icon_for("x.d.ts"), "typescript-def");
        assert_eq!(icon_for("App.tsx"), "react_ts");
        assert_eq!(icon_for("style.css"), "css");
        assert_eq!(icon_for("main.go"), "go");
        assert_eq!(icon_for("photo.JPG"), "image");
        assert_eq!(icon_for("LICENSE"), "certificate");
        assert_eq!(icon_for("unknownfile"), "document");
        assert_eq!(icon_for("weird.zzzz"), "document");
        assert_eq!(icon_for(".hidden"), "document");
    }

    #[test]
    fn every_mapping_has_an_svg() {
        // A typo in the tables would otherwise fall back silently.
        let names = ["dockerfile", "makefile", "cmakelists.txt", "package.json", "yarn.lock", "pnpm-lock.yaml", "bun.lock", "cargo.toml", "go.mod", "gemfile", "pyproject.toml", "poetry.lock", "uv.lock", "tsconfig.json", "jsconfig.json", ".gitignore", ".editorconfig", ".prettierrc", ".eslintrc", ".babelrc", ".nvmrc", "license", "readme.md", "changelog.md", "contributing.md", "code_of_conduct.md", "authors", "codeowners", "security.md", "todo.md", "claude.md", "caddyfile", "procfile", "robots.txt", "flake.nix", "vite.config.ts", "vitest.config.ts", "tailwind.config.js", "postcss.config.js", "renovate.json", "biome.json", "turbo.json", "vercel.json", "netlify.toml", "deno.json", "knip.json", "meson.build", "justfile"];
        for n in names {
            let id = by_file_name(n).unwrap();
            assert!(known(id), "{n} → {id} has no svg");
        }
        for ext in ["js", "jsx", "ts", "tsx", "html", "scss", "styl", "json", "yml", "xsl", "ini", "service", "sh", "ps1", "py", "ipynb", "rb", "kt", "sc", "gvy", "gradle", "h", "cc", "hh", "m", "mm", "cs", "fs", "rs", "pl", "ex", "erl", "clj", "el", "scm", "ml", "re", "hs", "jl", "v", "sql", "gql", "sol", "asm", "tf", "hcl", "pp", "tex", "bib", "md", "mdx", "adoc", "txt", "csv", "log", "vim", "cmake", "mk", "diff", "proto", "wasm", "glsl", "lock", "zip", "png", "ico", "mp3", "mp4", "srt", "doc", "ppt", "ttf", "pem", "key", "exe", "dll", "a", "jar", "class", "blend", "obj", "http", "url", "eml", "epub", "drawio", "excalidraw", "mmd", "puml", "j2", "hbs", "njk", "typ"] {
            let id = by_extension(ext).unwrap();
            assert!(known(id), ".{ext} → {id} has no svg");
        }
    }
}
